export async function listPostsEntries() {
  const posts = byId(await getCollection("posts"))
  const authorIds = new Set((await getCollection("authors")).map(entry => entry.id))
  for (const post of posts) {
    if (!authorIds.has(post.data.author)) throw new Error(`src/content/posts/${post.id}: field "author" is "${post.data.author}", which is not the id of any entry in src/content/authors/`)
  }
  return posts
}

import BaseLayout from "../../layouts/BaseLayout.astro"
import { listAuthorsEntries, listPostsEntries } from "../../lib/contentcatalog"

export async function getStaticPaths() {
  const entries = await listAuthorsEntries()
  return entries.map(entry => ({ params: { slug: entry.id }, props: { entry } }))
}

const { entry } = Astro.props
const posts = (await listPostsEntries())
  .filter(post => post.data.author === entry.id)
  .sort((a, b) => b.data.published.getTime() - a.data.published.getTime())
---
<BaseLayout title={`${entry.data.name} — Field Notes`} description={entry.data.bio ?? entry.data.name}>
  <h1>{entry.data.name}</h1>
  {entry.data.bio && <dl><dt>Bio</dt><dd>{entry.data.bio}</dd></dl>}
  <ol>
    {posts.map(post => (
      <li>
        <a href={`/posts/${post.id}/`}>{post.data.title}</a>
        <time datetime={post.data.published.toISOString().slice(0, 10)}>{post.data.published.toISOString().slice(0, 10)}</time>
      </li>
    ))}
  </ol>
</BaseLayout>
